import{_ as a,o as t,c as d,ae as o}from"./chunks/framework.C4zpkcTP.js";const y=JSON.parse('{"title":"Upgrading","description":"Upgrade Laravel Myanmar Payments from v2.2.7 to v4.0.0. New facade and config file, typed accessors, typed request and result classes, Request-based callbacks and a mapped PaymentStatus.","frontmatter":{"title":"Upgrading","description":"Upgrade Laravel Myanmar Payments from v2.2.7 to v4.0.0. New facade and config file, typed accessors, typed request and result classes, Request-based callbacks and a mapped PaymentStatus."},"headers":[],"relativePath":"laravel-myanmar-payments/upgrading.md","filePath":"laravel-myanmar-payments/upgrading.md"}'),s={name:"laravel-myanmar-payments/upgrading.md"};function n(r,e,c,i,l,h){return t(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><h2 id="from-a-v4-pre-release" tabindex="-1">From a v4 pre-release <a class="header-anchor" href="#from-a-v4-pre-release" aria-label="Permalink to &quot;From a v4 pre-release&quot;">​</a></h2><p>If you installed <code>v4.0.0-alpha.1</code>, one status was renamed to American English, with no alias:</p><table tabindex="0"><thead><tr><th>v4.0.0-alpha.1</th><th>v4.0.0</th></tr></thead><tbody><tr><td><code>PaymentStatus::Cancelled</code></td><td><code>PaymentStatus::Canceled</code></td></tr><tr><td><code>&#39;cancelled&#39;</code> (enum value)</td><td><code>&#39;canceled&#39;</code></td></tr></tbody></table><p>Update code that references the case, and any statuses you stored as <code>&#39;cancelled&#39;</code>. Gateway status literals keep their spelling: Wave Money still sends <code>PAYMENT_REQUEST_CANCELLED</code>, and it still maps to <code>PaymentStatus::Canceled</code>.</p><h2 id="from-v2-2-7-to-v4-0-0" tabindex="-1">From v2.2.7 to v4.0.0 <a class="header-anchor" href="#from-v2-2-7-to-v4-0-0" aria-label="Permalink to &quot;From v2.2.7 to v4.0.0&quot;">​</a></h2><p>v4 is a rewrite on top of <a href="/php-myanmar-payments/introduction.html"><code>laranex/php-myanmar-payments</code></a>. The rewrite was developed as v3, but v3 was never released: upgrade straight from v2.2.7 to v4.0.0. Every gateway now takes a typed request object and returns a typed result, and every exception extends <code>PaymentException</code>.</p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><p>PHP 8.1+ and Laravel 10 to 13. The package now requires <code>guzzlehttp/guzzle</code> ^7.4 or ^8.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/laravel-myanmar-payments:^4.0</span></span></code></pre></div><h3 id="facade-and-service-provider" tabindex="-1">Facade and service provider <a class="header-anchor" href="#facade-and-service-provider" aria-label="Permalink to &quot;Facade and service provider&quot;">​</a></h3><table tabindex="0"><thead><tr><th>v2.2.7</th><th>v4.0.0</th></tr></thead><tbody><tr><td><code>Laranex\\LaravelMyanmarPayments\\LaravelMyanmarPaymentsFacade</code></td><td><code>Laranex\\LaravelMyanmarPayments\\Facades\\MyanmarPayments</code></td></tr><tr><td>Alias <code>LaravelMyanmarPayments</code></td><td>Alias <code>MyanmarPayments</code></td></tr><tr><td><code>LaravelMyanmarPaymentsServiceProvider</code></td><td><code>MyanmarPaymentsServiceProvider</code></td></tr><tr><td><code>channel(&#39;...&#39;)</code></td><td>Typed accessors: <code>kbzPay()</code>, <code>waveMoney()</code>, <code>ayaPay()</code>, <code>yomaMmqr()</code>, <code>cyberSource()</code></td></tr></tbody></table><p>Both are auto-discovered. If you registered the old provider or alias by hand, replace them.</p><h3 id="starting-payments" tabindex="-1">Starting payments <a class="header-anchor" href="#starting-payments" aria-label="Permalink to &quot;Starting payments&quot;">​</a></h3><p>String channels and positional arguments are replaced with typed accessors and one request class per gateway, in <code>Laranex\\PhpMyanmarPayments\\&lt;Gateway&gt;\\&lt;Gateway&gt;PaymentData</code>.</p><table tabindex="0"><thead><tr><th>v2.2.7</th><th>v4.0.0</th></tr></thead><tbody><tr><td><code>channel(&#39;kbz_pay.pwaapp&#39;)-&gt;getPaymentScreenUrl($orderId, $amount, $nonceStr, $backendResultUrl)</code></td><td><code>kbzPay()-&gt;pwa(new KbzPayPaymentData(...))</code> → <code>RedirectPayment</code></td></tr><tr><td><code>channel(&#39;kbz_pay.qr&#39;)-&gt;getPaymentQr(...)</code></td><td><code>kbzPay()-&gt;qr($data)</code> → <code>QrPayment</code> (<code>qrString</code>)</td></tr><tr><td><code>channel(&#39;kbz_pay.app&#39;)-&gt;getPaymentData(...)</code></td><td><code>kbzPay()-&gt;app($data)</code> → <code>AppPayment</code> (<code>toArray()</code>)</td></tr><tr><td><code>channel(&#39;kbz_pay.*&#39;)-&gt;queryOrder($orderId, $nonceStr)</code></td><td><code>kbzPay()-&gt;status($orderId)</code> → <code>PaymentStatusResult</code></td></tr><tr><td><code>channel(&#39;wave_money&#39;)-&gt;getPaymentScreenUrl($items, $orderId, $amount, $merchantReferenceId, $backendResultUrl, ...)</code></td><td><code>waveMoney()-&gt;initiate(new WaveMoneyPaymentData(...))</code> → <code>RedirectPayment</code></td></tr><tr><td><code>channel(&#39;aya_pgw&#39;)-&gt;getPaymentServices()</code></td><td><code>ayaPay()-&gt;services()</code> → <code>list&lt;AyaPayService&gt;</code></td></tr><tr><td><code>channel(&#39;aya_pgw&#39;)-&gt;paymentRequest($orderId, $amount, $channel, $method, ...)</code></td><td><code>ayaPay()-&gt;initiate(new AyaPayPaymentData(...))</code> → <code>FormPayment</code></td></tr><tr><td><code>channel(&#39;aya_pgw&#39;)-&gt;paymentEnquiry($orderId)</code></td><td><code>ayaPay()-&gt;status($orderId)</code> → <code>PaymentStatusResult</code></td></tr><tr><td><code>channel(&#39;cyber_source.secure_acceptance&#39;)-&gt;getPaymentData($transactionId, $referenceNumber, $amount, ...)</code></td><td><code>cyberSource()-&gt;initiate(new CyberSourcePaymentData(...))</code> → <code>FormPayment</code></td></tr><tr><td><code>channel(&#39;yoma_mmqr&#39;)-&gt;getPaymentQr($orderNumber, $amount, $description)</code></td><td><code>yomaMmqr()-&gt;initiate(new YomaMmqrPaymentData(...))</code> → <code>QrPayment</code> (<code>qrImage</code>)</td></tr><tr><td><code>channel(&#39;yoma_mmqr&#39;)-&gt;checkoutOrder(...)</code> + <code>generateQr($orderNumber)</code></td><td><code>yomaMmqr()-&gt;initiate($data)</code> once, then <code>yomaMmqr()-&gt;renewQr($orderId)</code></td></tr><tr><td><code>channel(&#39;yoma_mmqr&#39;)-&gt;checkPaymentStatus($refLabel)</code></td><td><code>yomaMmqr()-&gt;status($payment-&gt;reference)</code> → <code>PaymentStatusResult</code></td></tr></tbody></table><p>Parameters share one vocabulary across gateways:</p><ul><li>The order id is <code>orderId</code>; the server-to-server URL is <code>callbackUrl</code>; the customer&#39;s return URL is <code>returnUrl</code>.</li><li>KBZ Pay&#39;s <code>$nonceStr</code>, CyberSource&#39;s <code>$transactionId</code> (<code>transaction_uuid</code>) and AYA&#39;s <code>$currencyCode</code> are handled internally. CyberSource&#39;s <code>$referenceNumber</code> is now <code>orderId</code>.</li><li>Wave Money items are <code>WaveMoneyItem</code> objects, the total defaults to their sum, and <code>merchantReferenceId</code> defaults to a random id. <code>returnUrl</code> and <code>description</code> are required (v2 fell back to <code>APP_URL</code> and the app name).</li><li>AYA takes an <code>AyaPayMethod</code> enum for <code>method</code>.</li><li>Amounts are <code>Amount|int</code>, never floats or numeric strings. See <a href="/laravel-myanmar-payments/amounts.html">Amounts</a>.</li><li>Request data is validated against each gateway&#39;s documented rules when it is built, and throws <code>InvalidPaymentDataException</code>.</li></ul><h3 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h3><p>v2 returned strings and arrays; v4 returns one class per flow. See <a href="/laravel-myanmar-payments/payment-flows.html">Payment Flows</a>.</p><table tabindex="0"><thead><tr><th>v2.2.7</th><th>v4.0.0</th></tr></thead><tbody><tr><td>KBZ PWA / Wave URL string</td><td><code>RedirectPayment::$url</code></td></tr><tr><td>KBZ QR string</td><td><code>QrPayment::$qrString</code></td></tr><tr><td>KBZ App <code>[&#39;orderInfo&#39;, &#39;sign&#39;, &#39;signType&#39;]</code></td><td><code>AppPayment::toArray()</code></td></tr><tr><td>AYA / CyberSource <code>[&#39;url&#39; =&gt; ..., &#39;data&#39; =&gt; ...]</code></td><td><code>FormPayment::$action</code> / <code>$fields</code>, or simply <code>redirect($payment-&gt;autoSubmitUrl)</code></td></tr><tr><td>Yoma <code>[&#39;refLabel&#39;, &#39;qrString&#39;, &#39;expiresInSeconds&#39;]</code></td><td><code>QrPayment::$reference</code>, <code>$qrImage</code>, <code>$expiresAt</code></td></tr></tbody></table><p>AYA Pay and CyberSource forms no longer need a page of your own: the package&#39;s <a href="/laravel-myanmar-payments/configuration.html#auto-submit-form-route">auto-submit form route</a> renders and posts them.</p><h3 id="callbacks" tabindex="-1">Callbacks <a class="header-anchor" href="#callbacks" aria-label="Permalink to &quot;Callbacks&quot;">​</a></h3><p>The <code>verify*()</code> methods returned a <code>bool</code> (or AYA&#39;s decoded payload). <code>handleCallback()</code> takes the request, throws <code>SignatureVerificationException</code> when verification fails and returns a <code>PaymentCallback</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// v2.2.7</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$channel </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> LaravelMyanmarPaymentsFacade</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">channel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;kbz_pay.qr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">abort_unless</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($channel</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">verifySignature</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($request), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">401</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// v4.0.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$callback </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MyanmarPayments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kbzPay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">handleCallback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($request);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($callback</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isSuccessful</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // $callback-&gt;orderId, $callback-&gt;gatewayReference, $callback-&gt;amount</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MyanmarPayments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">acknowledge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($callback);</span></span></code></pre></div><table tabindex="0"><thead><tr><th>v2.2.7</th><th>v4.0.0</th></tr></thead><tbody><tr><td><code>channel(&#39;kbz_pay.*&#39;)-&gt;verifySignature($request)</code></td><td><code>kbzPay()-&gt;handleCallback($request)</code></td></tr><tr><td><code>channel(&#39;wave_money&#39;)-&gt;verifyWaveSignature($request)</code></td><td><code>waveMoney()-&gt;handleCallback($request)</code></td></tr><tr><td><code>channel(&#39;aya_pgw&#39;)-&gt;verifySignature($payload, $checkSum)</code></td><td><code>ayaPay()-&gt;handleCallback($request)</code>, or <code>ayaPay()-&gt;verifyRedirect($request)</code> on the return page</td></tr><tr><td><code>channel(&#39;cyber_source.secure_acceptance&#39;)-&gt;verifySignature($request)</code></td><td><code>cyberSource()-&gt;handleCallback($request)</code></td></tr><tr><td><code>channel(&#39;yoma_mmqr&#39;)-&gt;verifySignature($request)</code></td><td><code>yomaMmqr()-&gt;handleCallback($request)</code></td></tr></tbody></table><ul><li>Branch on <code>$callback-&gt;status</code> (<code>PaymentStatus</code>) or <code>isSuccessful()</code>. v2&#39;s Wave check returned <code>false</code> for any status but <code>PAYMENT_CONFIRMED</code>; v4 verifies every status and maps it.</li><li>Return <code>MyanmarPayments::acknowledge($callback)</code> so each gateway gets the response it expects (KBZ Pay&#39;s plain <code>success</code>) and stops retrying.</li><li>Callback verification for KBZ Pay, Wave Money and AYA was fixed against their official specifications.</li><li>Yoma&#39;s <code>status()</code> returns <code>PaymentStatus::Expired</code> for an expired QR instead of throwing, and Yoma access tokens are now cached in your cache store.</li></ul><p>See <a href="/laravel-myanmar-payments/callbacks.html">Callbacks &amp; Status</a>.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>The config file is now <code>config/myanmar-payments.php</code> (publish tag <code>myanmar-payments-config</code>), replacing <code>config/laravel-myanmar-payments.php</code> (tag <code>laravel-myanmar-payments</code>). Publish the new file and move your changes over:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myanmar-payments-config&quot;</span></span></code></pre></div><ul><li>Every gateway uses its production endpoints. The <code>*_BASE_URL</code> variables (required for AYA and CyberSource in v2) are now optional overrides; to test against UAT, set them to the UAT URLs listed in <a href="/laravel-myanmar-payments/configuration.html#testing-against-uat">Testing Against UAT</a>.</li><li>The AYA block is renamed <code>aya_pgw</code> → <code>aya_pay</code>, read from <code>AYA_PAY_*</code> with the <code>AYA_PGW_*</code> names as fallbacks.</li><li>KBZ Pay&#39;s <code>base_url</code> and <code>pwa.base_redirect_url</code> keys are now <code>api_url</code> and <code>pwa_url</code>; the <code>KBZ_PAY_BASE_URL</code> and <code>KBZ_PAY_PWA_BASE_REDIRECT_URL</code> env names are unchanged. <code>KBZ_PAY_MERCHANT_NAME</code> is no longer used.</li><li>Wave Money redirects the customer to <code>WAVE_MONEY_AUTHENTICATE_URL</code> (the Wave host without the API port) instead of the API base URL.</li><li><code>MYANMAR_PAYMENTS_HTTP_TIMEOUT</code> (optional, 30 seconds by default), <code>MYANMAR_PAYMENTS_FORM_TTL_MINUTES</code>, <code>MYANMAR_PAYMENTS_CACHE_STORE</code> and the <code>form_route</code> options are new.</li><li>Every setting of the gateways you use except the HTTP timeout is required and has no default, including <code>MYANMAR_PAYMENTS_FORM_TTL_MINUTES</code> (for AYA Pay and CyberSource), <code>WAVE_MONEY_MERCHANT_NAME</code> (no <code>APP_NAME</code> fallback), <code>WAVE_MONEY_TIME_TO_LIVE_IN_SECONDS</code> and <code>YOMA_MMQR_API_VERSION</code>. CyberSource payments take <code>currency</code>, <code>transactionType</code> and <code>locale</code>.</li></ul><p>See <a href="/laravel-myanmar-payments/configuration.html">Configuration</a>.</p><h3 id="exceptions" tabindex="-1">Exceptions <a class="header-anchor" href="#exceptions" aria-label="Permalink to &quot;Exceptions&quot;">​</a></h3><p>v2 threw plain <code>Exception</code>s. v4 throws <code>PaymentException</code> subclasses: <code>InvalidPaymentDataException</code>, <code>ApiException</code> (with the gateway&#39;s code and message), <code>SignatureVerificationException</code> and <code>ConfigurationException</code>. See <a href="/laravel-myanmar-payments/references/errors.html">Errors</a>.</p><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><code>LaravelMyanmarPayments::channel()</code> and the per-channel classes (<code>KbzPayPwa</code>, <code>KbzPayQr</code>, <code>KbzPayApp</code>, <code>WaveMoney</code>, <code>AyaPgw</code>, <code>CyberSourceSecureAcceptance</code>, <code>YomaMmqr</code>) in the <code>Laranex\\LaravelMyanmarPayments</code> namespace.</li><li>KBZ Pay&#39;s refund query (<code>queryOrder()</code> with <code>$refundRequestNo</code>).</li><li>Yoma&#39;s public <code>getAccessToken()</code>; tokens are fetched and cached internally (<code>yomaMmqr()-&gt;forgetToken()</code> drops the cached one).</li></ul>`,37)])])}const m=a(s,[["render",n]]);export{y as __pageData,m as default};
